package main

import (
	"net/http"

	"example.com/api/db"
)

var conn = &db.DB{}

func main() {
	_ = conn
	http.ListenAndServe(":8080", nil)
}

// Package db is the service's database handle.
package db

import "context"

// DB is a database connection.
type DB struct{}

// Ping checks the connection.
func (*DB) Ping(ctx context.Context) error { return ctx.Err() }

